import { useEffect, useRef, useState } from 'react';
import { ArrowLeft, Calendar, Type, Link2, Check } from 'lucide-react';
import { Button } from '@perimeter/ui/button';
import { Empty, EmptyHeader, EmptyTitle, EmptyDescription } from '@perimeter/ui/empty';
import { Skeleton } from '@perimeter/ui/skeleton';
import { SortSelect } from '@perimeter/ui/sort-select';
import { SkeletonTransition } from '@perimeter/ui/skeleton-transition';
import { useSafeHtml } from '@perimeter/ui/hooks/use-safe-html';
import { useCopiedFlash } from '@perimeter/ui/hooks/use-copied-flash';
import { useSermonDetail, useSermons } from '@perimeter/api-hooks';
import type { SermonListViewProps, SermonsConfig, SortField, SortOrder } from '../../types';
import { sermonImageUrl } from '../../lib/format';
import { defined } from '../../lib/query-params';
import { MediaTabs } from '../players/MediaTabs';
import { DateSpeakerLine, MediaCard } from '../ui/MediaCard';
import { sermonCardMeta } from './SermonInfo';
import { BRAND_BUTTON } from '../../lib/button-styles';
import { cn } from '@perimeter/ui/utils/cn';

interface SermonDetailProps extends Pick<SermonListViewProps, 'onSeriesClick' | 'onSpeakerClick'> {
  id: number;
  config: SermonsConfig;
  onBack: () => void;
  onSermonClick?: ((id: number) => void) | undefined;
}

const SORT_FIELDS = [
  {
    value: 'date',
    label: 'Date',
    icon: <Calendar className="h-3.5 w-3.5" />,
  },
  {
    value: 'title',
    label: 'Title',
    icon: <Type className="h-3.5 w-3.5" />,
  },
];

export function SermonDetail({
  id,
  config,
  onBack,
  onSermonClick,
  onSeriesClick,
  onSpeakerClick,
}: SermonDetailProps) {
  const { data, isLoading, error } = useSermonDetail(id);
  const sermon = data?.data;
  const safeDescription = useSafeHtml(sermon?.description);
  const showRelated = (config.display ?? 'full') !== 'headless';
  const [sortField, setSortField] = useState<SortField>('date');
  const [sortDirection, setSortDirection] = useState<SortOrder>('desc');
  const { copied, flash } = useCopiedFlash(2000);
  const titleRef = useRef<HTMLHeadingElement>(null);

  // The selected sermon is already encoded in the URL via nuqs (`?id=…`), so
  // the current href is a shareable deep link. Copy it to the
  // clipboard and flash a confirmation.
  const handleCopyLink = () => {
    void navigator.clipboard?.writeText(window.location.href);
    flash();
  };

  useEffect(() => {
    if (sermon) titleRef.current?.focus();
  }, [sermon]);

  // Gated on the parent fetch: while the sermon is in flight, seriesId would
  // be dropped and the hook would fire an unfiltered 50-row listing that is
  // thrown away as soon as the real seriesId arrives. The config's pinned
  // seriesTypeId keeps the related list consistent with the browse view.
  const { data: seriesData, error: relatedError } = useSermons(
    defined({
      seriesId: sermon?.series.id ? String(sermon.series.id) : undefined,
      seriesTypeId: config.seriesTypeId || undefined,
      // Sermons sort only over date/title; 'count' is series-only.
      sort: sortField === 'count' ? 'date' : sortField,
      order: sortDirection,
      perPage: 50,
    }),
    { enabled: !!sermon?.series.id },
  );

  const relatedSermons = (seriesData?.data.sermons ?? []).filter((s) => s.id !== id);
  // Same meta as the cards: series, then bold date · speaker, linked when the
  // filter can be shown.
  const headerMeta = sermon ? sermonCardMeta(sermon, { onSeriesClick, onSpeakerClick }) : null;
  // `hideBack` is for a dedicated sermon-details page that has its own "Back to
  // All Sermons" link, so the widget shouldn't add a second one.
  const backButton = config.hideBack ? null : (
    <Button variant="primary" size="sm" onClick={onBack} className={cn('mb-4', BRAND_BUTTON)}>
      <ArrowLeft className="h-4 w-4" /> Back
    </Button>
  );

  if (error) {
    return (
      <div>
        {backButton}
        <Empty>
          <EmptyHeader>
            <EmptyTitle>Sermon not found</EmptyTitle>
            <EmptyDescription>
              This sermon may have been removed or is unavailable.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      </div>
    );
  }

  return (
    <div>
      {backButton}
      <SkeletonTransition
        isLoading={isLoading}
        skeleton={
          <div className="space-y-4">
            <Skeleton className="h-8 w-2/3" />
            <Skeleton className="h-5 w-1/2" />
            <Skeleton className="h-64 w-full rounded-lg" />
            <Skeleton className="h-24 w-full" />
          </div>
        }
      >
        {sermon && (
          <div className="space-y-6">
            <div>
              <div className="flex items-start justify-between gap-3">
                <h2
                  ref={titleRef}
                  tabIndex={-1}
                  className="font-serif text-[32px] font-normal leading-tight text-fg outline-hidden"
                >
                  {sermon.title}
                </h2>
                <Button
                  variant="primary"
                  size="sm"
                  onClick={handleCopyLink}
                  aria-label="Copy link to this sermon"
                  className={cn('shrink-0', BRAND_BUTTON)}
                >
                  {copied ? <Check className="h-4 w-4" /> : <Link2 className="h-4 w-4" />}
                  {copied ? 'Copied' : 'Copy link'}
                </Button>
              </div>
              <div className="mt-2 truncate text-sm text-muted-fg">{headerMeta?.topRight}</div>
              <DateSpeakerLine
                date={headerMeta?.topLeft}
                speaker={headerMeta?.bottomLeft}
                className="mt-1.5"
              />
              {sermon.scriptureLinks && (
                <p className="mt-1.5 text-sm text-muted-fg">Scripture: {sermon.scriptureLinks}</p>
              )}
            </div>
            <MediaTabs links={sermon.links} />
            {sermon.description && (
              <div className="rounded-lg bg-muted p-4">
                <h3 className="mb-2 font-serif text-2xl font-normal">About this sermon</h3>
                <div
                  className="text-base leading-relaxed text-muted-fg [&_a]:text-primary [&_a]:underline [&_li]:my-0.5 [&_ol]:my-2 [&_ol]:list-decimal [&_ol]:pl-5 [&_p]:my-2 [&_p:first-child]:mt-0 [&_p:last-child]:mb-0 [&_ul]:my-2 [&_ul]:list-disc [&_ul]:pl-5"
                  dangerouslySetInnerHTML={safeDescription}
                />
              </div>
            )}

            {/* Related fetch failed: a quiet inline note, not a full error
                block — the sermon itself loaded fine. */}
            {showRelated && relatedError && (
              <p data-slot="related-error" className="text-sm text-muted-fg">
                Couldn&rsquo;t load more sermons from this series.
              </p>
            )}

            {/* More from this series */}
            {showRelated && !relatedError && relatedSermons.length > 0 && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="font-serif text-2xl font-normal">More from this series</h3>
                  <SortSelect
                    variant="ghost"
                    sortField={sortField}
                    sortDirection={sortDirection}
                    onSortFieldChange={(f: string) => setSortField(f as SortField)}
                    onSortDirectionChange={(d: SortOrder) => setSortDirection(d)}
                    fields={SORT_FIELDS}
                  />
                </div>
                <div className="divide-y divide-border">
                  {relatedSermons.map((s) => (
                    <MediaCard
                      key={s.id}
                      viewMode="row"
                      imageUrl={s.bannerUrl ?? sermonImageUrl(s.id, config.apiUrl)}
                      imageAlt={s.title}
                      title={s.title}
                      description={s.shortDescription}
                      {...sermonCardMeta(s, {})}
                      onClick={() => onSermonClick?.(s.id)}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </SkeletonTransition>
    </div>
  );
}
